const body = $input.first().json.body;
if (!body || !body.data || !Array.isArray(body.data.fields)) {
  throw new Error('Structure Tally invalide');
}
const fields = body.data.fields;

// Résout un champ
function resolve(field) {
  if (!field) return 'Non renseigné';
  const v = field.value;
  if (v === null || v === undefined || v === '' || v === false) return 'Non renseigné';
  if (typeof v === 'boolean') return v ? 'Oui' : 'Non';
  if (Array.isArray(v) && field.options && field.options.length > 0) {
    const texts = v.map(uuid => {
      const opt = field.options.find(o => o.id === uuid);
      return opt ? opt.text : uuid;
    }).filter(Boolean);
    return texts.length > 0 ? texts.join(', ') : 'Non renseigné';
  }
  if (Array.isArray(v)) return v.join(', ') || 'Non renseigné';
  return String(v).trim() || 'Non renseigné';
}

// Cherche par label (fuzzy match)
function getByLabel(...labels) {
  const normalizedLabels = labels.map(l => l.toLowerCase().trim());
  const f = fields.find(field => {
    if (!field.label) return false;
    const fl = field.label.toLowerCase();
    return normalizedLabels.some(nl => fl.includes(nl));
  });
  return f ? resolve(f) : 'Non renseigné';
}

// Détection langue via payload root de Tally ou labels spécifiques
const langPayload = body.data.formLanguage || body.data.lang || '';
const langueRaw = getByLabel('Langue', 'Language', 'Langue préférée', 'Preferred language');
const isEnglish = langPayload.toLowerCase().includes('en') || 
                  langueRaw.toLowerCase().includes('en') || 
                  langueRaw.toLowerCase().includes('english') ||
                  langueRaw === 'English';

const langue = isEnglish ? 'en' : 'fr';

// Nettoyage de l'ID (certains paramètres peuvent inclure des suffixes comme emojis/langue)
const rawId = body.data.respondentId || '';
const respondentId = rawId.trim().split(/[\s🇺🇸🇬🇧🇫🇷]/)[0] || rawId;

return [{
  json: {
    respondentId,
    submissionId: body.data.submissionId || '',
    nom:        getByLabel('Prénom et Nom', 'Nom complet', 'Nom', 'Name'),
    email:      getByLabel('Email professionnel', 'Email', 'Adresse email'),
    site:       getByLabel('Site e-commerce (URL)', 'Site web', 'URL du site', 'Website'),
    plateforme: getByLabel('Plateforme utilisée', 'Plateforme e-commerce', 'Platform'),
    ca:         getByLabel('Taille de la boutique', 'Chiffre d\'affaires mensuel', 'CA mensuel', 'Revenue'),
    probleme:   getByLabel('Problème principal', 'Probleme principal', 'Main problem'),
    objectif:   getByLabel('Objectif business principal', 'Objectif principal', 'Goal'),
    budget:     getByLabel('Budget estimé', 'Budget mensuel', 'Budget'),
    urgence:    getByLabel('Urgence', 'Délai souhaité', 'Timeline'),
    autoExist:  getByLabel('Automatisations déjà en place', 'Automatisations existantes', 'Existing tools'),
    source:     getByLabel('Source de découverte', 'Source', 'How did you find us'),
    langue
  }
}];

const rows = $input.all().map(i => i.json).filter(r => r.email);
const lead = $('Extraire données Tally').first().json;
const alreadyDone = rows.length > 0;
return [{ json: { ...lead, alreadyDone } }];

