const client = $input.first().json;
const htmlString = client.html;

// Convertit le HTML string en binaire pour Google Drive upload
const buffer = Buffer.from(htmlString, 'utf8');

return [{
  json: { ...client },
  binary: {
    data: await this.helpers.prepareBinaryData(
      buffer,
      'Audit_Nexus_' + (client.nom || 'client').replace(/ /g,'_') + '.html',
      'text/html'
    )
  }
}];
